import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation to test set membership with a given false positive rate.
    It uses a bit array to store bits and multiple hash functions to reduce the chances of collisions.

    Design choices:
    - Optimal size of the bit array and number of hash functions calculated based on the 
      expected number of items and desired false positive rate.
    - Simple hash functions derived from `hashlib` to ensure uniform distribution of hashed values.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.bit_array_size = self._optimal_bit_array_size()
        self.num_hashes = self._optimal_number_of_hash_functions()
        self.bit_array = [0] * self.bit_array_size

    def _optimal_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return int(-self.expected_items * math.log(self.false_positive_rate) / (math.log(2) ** 2))

    def _optimal_number_of_hash_functions(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((self.bit_array_size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate hash values for the given item using multiple hash functions."""
        hash_values = []
        for i in range(self.num_hashes):
            # Create a unique hash for each function by varying the input
            hash_object = hashlib.md5(f"{item}{i}".encode()).hexdigest()
            hash_value = int(hash_object, 16) % self.bit_array_size
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom filter."""
        for hash_value in self._hashes(item):
            if self.bit_array[hash_value] == 0:
                return False
        return True

