class BloomFilter:
    """
    A Bloom Filter implementation that provides a means to test
    membership of elements with a specified false positive rate.

    The design utilizes an optimal number of hash functions and
    appropriate bit array size to reduce the chance of false positives based on
    expected items and desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.size = self.optimal_size(expected_items, false_positive_rate)
        self.num_hashes = self.optimal_hash_count(self.size, expected_items)
        self.bit_array = [0] * self.size

    def optimal_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((m / n) * math.log(2))

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hashes):
            hash_value = self.hash(item, i)
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for i in range(self.num_hashes):
            hash_value = self.hash(item, i)
            if self.bit_array[hash_value] == 0:
                return False
        return True

    def hash(self, item: str, seed: int) -> int:
        """Create a hash value for the item using SHA-256 and a seed."""
        hash_input = f"{item}{seed}".encode('utf-8')
        hash_digest = hashlib.sha256(hash_input).hexdigest()
        return int(hash_digest, 16) % self.size

