    This implementation creates a bit array based on the expected number of items
    and the desired false positive rate. The size of the bit array and the number
    of hash functions are calculated using standard Bloom Filter formulas.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._calculate_bit_array_size()
        self.num_hashes = self._calculate_number_of_hashes()
        self.bit_array = [0] * self.size

    def _calculate_bit_array_size(self) -> int:
        """Calculate optimal size of the bit array."""
        return math.ceil(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_number_of_hashes(self) -> int:
        """Calculate optimal number of hash functions."""
        return max(1, round((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Get a list of hash values for the item using multiple hash functions."""
        hash_values = []
        for i in range(self.num_hashes):
            # Create a unique hash using a combination of item and i
            hash_input = f"{item}-{i}".encode()
            hash_value = int(hashlib.md5(hash_input).hexdigest(), 16) % self.size
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all(self.bit_array[index] == 1 for index in self._hashes(item))

