import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation to test membership of items in a set with a given 
    false positive rate. This implementation uses bit manipulation and multiple hash 
    functions based on the optimal parameters calculated from the expected number of items 
    and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal bit array size (m)
        self.size = self._get_optimal_size()

        # Calculate optimal number of hash functions (k)
        self.num_hashes = self._get_optimal_num_hashes()

        self.bit_array = [0] * self.size

    def _get_optimal_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil((self.expected_items * math.log(self.false_positive_rate)) / math.log(1 / (math.pow(2, math.log(2)))))

    def _get_optimal_num_hashes(self) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash value for the given item using a specific seed."""
        hash_object = hashlib.md5((item + str(seed)).encode())
        return int(hash_object.hexdigest(), 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item may be in the Bloom filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            if self.bit_array[index] == 0:
                return False
        return True
